design.css:
/* Reel — the animepahe look. Numbers from docs/theme-references/animepahe.md (computed styles of the
   live site); the per-element table is in the parity draft's measure.md. */

/* ---------- Header: one 47 px black row, content in the 1100 px container ---------- */
:scope { --theme-top-row: 47px; }
[data-slot="nav.top"] {
  background: #000;
  border-bottom: 0;
  padding-left: max(12px, calc((100vw - 1100px) / 2));
  padding-right: max(12px, calc((100vw - 1100px) / 2));
  gap: 0;
}
[data-slot="nav.top"] [data-part="nav.item"] {
  height: 37px;
  padding: 8px 15px;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.4);
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  line-height: 21px;
  text-transform: lowercase;
}
[data-slot="nav.top"] [data-part="nav.item"][data-active] { color: #fff; background: rgba(0, 0, 0, 0.4); }
[data-slot="nav.top"] [data-part="nav.item"]:hover { color: #d5015b; background: rgba(0, 0, 0, 0.4); }
/* The search field ends the row at the container's right edge, as on the site; izumi's own
   incognito/settings/account buttons sit just before it. */
[data-slot="nav.top"] :has(> [data-part="search.field"]) { order: 99; width: 225px; margin-left: 10px; margin-right: 0; }
[data-slot="nav.top"] [data-part="search.field"] {
  height: 36px;
  padding-left: 32px;
  border: 0;
  border-radius: 0;
  background: #e7edf3;
  color: #667d99;
  font-size: 13px;
}
[data-slot="nav.top"] [data-part="nav.action"] { border-radius: 0; color: #fff; }
[data-slot="nav.top"] [data-part="nav.action"]:hover { color: #d5015b; background: transparent; }

/* ---------- Home: "Latest Releases", 3 × 360×202 cards with 10 px gutters ---------- */
[data-slot="home"] { max-width: 1132px; margin-left: auto; margin-right: auto; padding: 24px 16px 64px; }
[data-slot="block.latest-episodes"] { padding-left: 0; padding-right: 0; }
/* Phones: the Bootstrap container's 15 px gutters, one 360 px-wide card per row at 390 px. */
@media (max-width: 640px) {
  [data-slot="home"] { padding-left: 15px; padding-right: 15px; }
}
[data-slot="block.latest-episodes"] [data-part="block.title"] {
  font-size: 32px;
  font-weight: 300;
  line-height: 38.4px;
  color: #eee;
  margin: 0 0 13px;
}
[data-slot="block.latest-episodes"] :has(> [data-part="block.item"]) { gap: 10px; }
[data-slot="block.latest-episodes"] [data-part="block.item"] > button { border-radius: 0 !important; background: #000 !important; }
[data-slot="block.latest-episodes"] [data-part="episode.still"] img { transform: none !important; }
/* The site's overlay: clear to 70 %, then to rgba(0,0,0,.75) at the bottom edge. */
[data-slot="block.latest-episodes"] [data-part="episode.still"] + span {
  background-image: linear-gradient(transparent 70%, rgba(0, 0, 0, 0.75)) !important;
}
/* Hover: the magenta play triangle in the middle of the still. */
[data-slot="block.latest-episodes"] [data-part="block.item"] > button::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  margin: -24px 0 0 -14px;
  border-left: 36px solid #d5015b;
  border-top: 24px solid transparent;
  border-bottom: 24px solid transparent;
  opacity: 0;
  pointer-events: none;
}
[data-slot="block.latest-episodes"] [data-part="block.item"] > button:hover::after { opacity: 1; }
[data-slot="block.latest-episodes"] [data-part="card.title"] {
  left: 15px !important;
  bottom: 12px !important;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 19.2px;
  color: #fff;
  text-shadow: 0 1px 2px #000;
}
[data-slot="block.latest-episodes"] [data-part="episode.number"] {
  right: 15px !important;
  bottom: 12px !important;
  font-size: 19.2px;
  font-weight: 600;
  line-height: 19.2px;
}
[data-slot="block.latest-episodes"] [data-part="episode.number"] svg { color: #28a745; }

/* Pager « ‹ n › »: Bootstrap items, only the current page number shows. */
[data-part="pagination"] { gap: 0; margin-top: 16px; }
[data-part="pagination"] > span { display: none; }
[data-part="pagination"] [data-part="page-number"]:not([data-active]) { display: none; }
[data-part="pagination"] button {
  height: 38px;
  min-width: 35px;
  margin-left: -1px;
  padding: 8px 12px;
  border: 1px solid #000;
  border-radius: 0;
  background: #111;
  color: #a20145;
  font-size: 16px;
  font-weight: 400;
  line-height: 20px;
}
[data-part="pagination"] [data-part="page-number"][data-active] { background: #d5015b; color: #fff; }

/* ---------- Series page (desktop): one grid in the 1100 px container ----------
   poster 220 | title, Japanese line, tabs, score + actions, the tab's content | facts 250;
   the episode grid runs the full width under it. */
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] {
  display: grid;
  grid-template-columns: 220px max-content minmax(0, 1fr) 250px;
  grid-template-rows: auto auto auto auto auto 1fr;
  column-gap: 30px;
  align-items: start;
  max-width: 1132px;
  margin: -182px auto 0 !important;
  padding: 0 16px 64px !important;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > div:has(> [data-part="detail.poster"]),
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] div:has(> [data-part="detail.title"]) { display: contents; }
/* Everything else in the column (zero specificity, so the placements below win). */
:where([data-slot="detail"][data-variant="desktop"] [data-part="detail.content"]) > *,
:where([data-slot="detail"][data-variant="desktop"] div:has(> [data-part="detail.title"])) > * { grid-column: 2 / 4; margin: 0; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.poster"] {
  grid-column: 1; grid-row: 1 / 7; width: 220px !important; height: 330px; object-fit: cover; border-radius: 0; box-shadow: none;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.title"] {
  grid-column: 2 / -1; grid-row: 1; padding-top: 82px;
  font-family: var(--font-display); font-size: 32px; font-weight: 500; line-height: 38.4px; color: #fff;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.alt-title"] {
  grid-column: 2 / -1; grid-row: 2; margin-bottom: 8px;
  font-size: 17.6px; font-weight: 600; line-height: 21.12px; color: #fff;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > [data-part="tabs"] { grid-column: 2 / -1; grid-row: 3; margin: 0 0 15px; padding: 0; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.header"] { grid-column: 2; grid-row: 4; align-self: center; margin-bottom: 15px; font-size: 16px; font-weight: 700; color: #eee; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] { grid-column: 3; grid-row: 4; margin-bottom: 15px; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > [data-part="tabs"] + * { grid-row: 5; max-width: none; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.facts"] { grid-column: 4; grid-row: 4 / 7; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > div:has(> [data-slot="detail.episodes"]) { grid-column: 1 / -1; grid-row: 7; margin-top: 30px; }

[data-slot="detail"] [data-part="detail.synopsis"] { font-size: 16px; line-height: 24px; color: #eee; }
/* Studio and start date repeat the facts column; the synonyms stay. */
[data-slot="detail"] [data-part="detail.synopsis"] ~ dl [data-key="studio"],
[data-slot="detail"] [data-part="detail.synopsis"] ~ dl [data-key="aired"] { display: none; }

/* Facts column: "Label: value" lines, 12 px, labels bold; genres as tags under a divider. */
[data-part="detail.facts"][data-variant="table"] { display: block; font-size: 12px; line-height: 18px; color: #eee; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"] { display: block; margin-bottom: 3px; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"] { display: inline; font-weight: 700; color: #eee; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"]::after { content: ":"; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.value"] { display: inline; margin-left: 4px; color: #eee; white-space: normal; }
[data-part="detail.facts"] [data-part="fact.value"] a { color: #d5015b; }
[data-part="detail.facts"][data-variant="table"] [data-key="genres"] { margin-top: 12px; padding-top: 12px; border-top: 1px solid #222; }
[data-part="detail.facts"][data-variant="table"] [data-key="genres"] [data-part="fact.label"] { display: none; }
[data-part="detail.facts"][data-variant="table"] [data-key="genres"] [data-part="fact.value"] { display: flex; flex-wrap: wrap; gap: 4px; margin: 0; font-size: 0; }
[data-part="detail.facts"][data-variant="table"] [data-key="genres"] a {
  min-width: 76px; height: 22px; padding: 0 10px; background: #222; color: #d5015b;
  font-size: 12px; font-weight: 700; line-height: 22px; text-align: center; text-decoration: none;
}

[data-slot="detail"] [data-part="button"],
[data-slot="detail"] [data-part="detail.list-button"],
[data-slot="detail"] [data-part="detail.actions"] > * { border-radius: 0; }
[data-slot="detail"] [data-part="detail.actions"] { gap: 6px; }
[data-slot="detail"] [data-part="detail.actions"] > * { height: 36px; min-height: 36px; font-size: 14px; }
[data-slot="detail"] [data-part="detail.actions"] [data-part="button"] { padding-left: 14px; padding-right: 14px; }

/* Tabs: 180 × 50, 16 px / 400 #f1f1f1, the active one underlined magenta. */
[data-slot="detail"] [data-part="tabs"] { gap: 0; }
[data-slot="detail"] [data-part="tab"] {
  width: 180px; height: 50px; justify-content: center; text-align: center;
  font-size: 16px; font-weight: 400; color: #f1f1f1; border-radius: 0;
}
[data-slot="detail"] [data-part="tab"][data-active] { color: #fff; }
[data-slot="detail"] [data-part="tab"][data-active] > span { height: 2px; border-radius: 0; background: #d5015b; }

/* Episodes: a #222 bar "Episodes (n)" with the sort toggle at its right, then 3 × 360×202 stills. */
[data-slot="episodes.toolbar"][data-variant="header"] {
  height: 45px; margin-bottom: 10px; padding: 0 0 0 15px; background: #222; border-radius: 0; align-items: center;
}
[data-part="episodes.heading"] { font-size: 16px; font-weight: 400; color: #eee; }
[data-part="episodes.count"] { font-size: 16px; font-weight: 400; color: #eee; }
[data-part="episodes.count"]::before { content: "("; }
[data-part="episodes.count"]::after { content: ")"; }
/* The order toggle reads "asc" / "desc" as on the site. */
[data-part="episodes.sort"][data-dir] { font-size: 0 !important; gap: 0 !important; }
[data-part="episodes.sort"][data-dir] svg { display: none; }
[data-part="episodes.sort"][data-dir="asc"]::after { content: "asc"; font-size: 14px; }
[data-part="episodes.sort"][data-dir="desc"]::after { content: "desc"; font-size: 14px; }
[data-slot="episodes.toolbar"] button { height: 45px; border-radius: 0; background: transparent; color: #eee; font-size: 14px; font-weight: 400; }
[data-slot="detail.episodes"] [data-part="episodes.grid"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 10px !important; }
[data-slot="detail.episodes"] [data-part="episode"],
[data-slot="detail.episodes"] [data-part="episode"] * { border-radius: 0; }
[data-slot="detail.episodes"] [data-part="badge"] { display: none; }
[data-part="ep.card"]::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background-image: linear-gradient(transparent 70%, rgba(0, 0, 0, 0.75));
}
[data-part="ep.runtime"] {
  z-index: 1; left: 15px !important; bottom: 12px !important; padding: 2px 6px; border-radius: 3px;
  background: rgba(0, 0, 0, 0.7); color: #fff; font-size: 11px; font-weight: 400; line-height: 16px;
}
[data-part="ep.no"] {
  z-index: 1; right: 15px !important; bottom: 12px !important;
  color: #fff; font-size: 19.2px; font-weight: 700; line-height: 19.2px; text-shadow: 0 1px 2px #000;
}
[data-part="ep.progress"] { z-index: 1; }
[data-slot="detail.episodes"] [data-part="episode"][data-state="unaired"] { opacity: 0.45; }
[data-part="episodes.pager"] [data-part="page-number"] {
  height: 40px; padding: 8px 12px; border: 1px solid #000; border-radius: 0; background: #111; color: #a20145; font-size: 16px;
}

/* Watch page: animepahe's play page. A 1100px column with the video 25px under the header, then a
   #222 bar of four equal dropdowns (server, episode, fansub · quality, download) opening upward in
   white menus, the poster + "Title - 12" info block, and the discussion below as part of the page. */
[data-slot="watch.page"] { padding-top: 25px; }
[data-slot="watch.toolbar"] { margin-top: 15px; background: #222 !important; color: #eee !important; }
[data-slot="watch.toolbar"] > div + div::before {
  content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: rgba(255, 255, 255, 0.12); z-index: 1;
}
[data-part="watch.toolbar.item"] {
  position: relative; height: 45px !important; padding: 12px 16px !important; font-size: 14px !important; font-weight: 400;
  color: #eee !important; background: transparent !important;
}
[data-part="watch.toolbar.item"] svg { display: none; }
[data-part="watch.toolbar.item"]::after {
  content: ""; position: absolute; top: 20px; right: 15px;
  border-left: 4px solid transparent; border-right: 4px solid transparent; border-bottom: 4px solid #eee;
}
[data-part="watch.toolbar.menu"] {
  left: 0 !important; transform: none !important; min-width: 100% !important; margin-bottom: 2px !important;
  padding: 8px 0 !important; border: 1px solid rgba(0, 0, 0, 0.15) !important; border-radius: 0 !important;
  background: #fff !important; color: #212529 !important; box-shadow: none !important;
}
[data-part="watch.toolbar.option"] { padding: 4px 24px !important; font-size: 14px; color: #212529; }
[data-part="watch.toolbar.menu"][data-item="episode"] [data-part="watch.toolbar.option"] { text-align: center !important; }
[data-part="watch.toolbar.option"]:hover { background: #f8f9fa !important; color: #16181b !important; }
[data-part="watch.toolbar.option"][data-state="active"] { background: #d5015b !important; color: #eee !important; }
[data-slot="watch.info"] {
  position: relative; display: block !important; min-height: 143px; margin: 15px 0 16px;
  padding: 15px 0 15px 95px !important; background: transparent !important; color: #999 !important; font-size: 14px !important;
}
[data-part="watch.info.poster"] { position: absolute !important; left: 0; top: 15px; width: 80px !important; border-radius: 0 !important; }
[data-part="watch.info.poster"] img { aspect-ratio: auto !important; height: 113px; }
[data-part="watch.info.title"] { font-size: 16px !important; font-weight: 600 !important; line-height: 21px; color: #fff !important; }
[data-part="watch.info.title"] a:hover { text-decoration: none !important; color: #d5015b; }
[data-part="watch.info.meta"], [data-part="watch.info.season"] { line-height: 21px; }
/* The discussion where the embed sits on the site: tabs with a rounded top corner over the panel. */
[data-part="watch.block"][data-block="comments"] { margin-top: 80px; }
[data-slot="watch.comments"] { background: transparent !important; }
[data-part="comments.header"] { display: none !important; }
[data-part="comments.tabs"] { gap: 0 !important; padding: 0 !important; border: 0 !important; }
[data-part="comments.tab"] {
  height: 45px; padding: 0 20px !important; border-radius: 0 16px 0 0 !important; font-size: 14px !important; font-weight: 600 !important;
  background: #1c1c1c !important; color: #9a9a9a !important;
}
[data-part="comments.tab"][data-active] { background: #323232 !important; color: #f5f5f5 !important; }
